(function(){'use strict';function cfg(role){if(role==='doctor'){var d=window.dior_doctor_vars||{};return{ajaxUrl:d.ajax_url||window.diorDocAjax||'/wp-admin/admin-ajax.php',nonce:d.nonce||window.diorDocNonce||'',get:'dior_doc_chat_get',send:'dior_doc_chat_send'}}
var p=window.dior_patient_live_vars||window.dior_vars||{};return{ajaxUrl:p.ajax_url||'/wp-admin/admin-ajax.php',nonce:p.nonce||p.portal_nonce||'',get:'dior_patient_chat_get',send:'dior_patient_chat_send'}}
function me(role){return Number(role==='doctor'?((window.dior_doctor_vars||{}).current_user_id||0):((window.dior_patient_live_vars||window.dior_vars||{}).current_user_id||0))}
function myName(role){return role==='doctor'?((((window.dior_doctor_vars||{}).doctor_profile||{}).full_name)||'Doctor'):((((window.dior_patient_live_vars||window.dior_vars||{}).patient_profile||{}).full_name)||'Patient')}
function time(v){if(!v)return'';var d=new Date(String(v).replace(' ','T'));return isNaN(d.getTime())?String(v):d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function container(panel,role){return panel.querySelector(role==='doctor'?'#dior-doc-chat-messages-container, #dior-doc-chat-container':'#dior-chat-messages-container')}
function render(panel,rows,role){var c=container(panel,role);if(!c)return;var uid=me(role);c.innerHTML='';rows.forEach(function(m){var mine=Number(m.sender_user_id)===uid;var doctorMsg=role==='doctor'?mine:!mine;var row=document.createElement('div');row.className=doctorMsg?'dior-ic-044f0b27b0':'dior-ic-68494619df';var img=document.createElement('img');img.className='dior-ic-2061ceb509';img.alt=doctorMsg?'Doctor':'Patient';img.src=doctorMsg?'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&q=80&w=100':'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&q=80&w=100';var wrap=document.createElement('div');var meta=document.createElement('div');meta.className=doctorMsg?'dior-ic-2c31c3e1bf':'dior-ic-af753e564d';var name=document.createElement('span');name.className='dior-ic-a55dcb6086';name.textContent=mine?myName(role):(doctorMsg?(panel.getAttribute('data-doctor-name')||'Doctor'):(panel.getAttribute('data-patient-name')||'Patient'));var stamp=document.createElement('span');stamp.className='dior-ic-37f02fdd9f';stamp.textContent=time(m.created_at);meta.appendChild(name);meta.appendChild(stamp);var body=document.createElement('div');body.className=doctorMsg?'dior-ic-accfff7f7f':'dior-ic-02827fb633';body.textContent=String(m.message||'');wrap.appendChild(meta);wrap.appendChild(body);row.appendChild(img);row.appendChild(wrap);c.appendChild(row)});c.scrollTop=c.scrollHeight}
function request(panel,type,msg){var role=panel.getAttribute('data-dior-chat-role'),uid=panel.getAttribute('data-appointment-uid'),c=cfg(role);if(!role||!uid||!c.nonce)return Promise.resolve(null);var d=new FormData();d.append('action',type==='get'?c.get:c.send);d.append('nonce',c.nonce);d.append('appointment_uid',uid);if(type==='send')d.append('message',msg||'');return fetch(c.ajaxUrl,{method:'POST',credentials:'same-origin',body:d}).then(function(r){return r.json()})}
function bind(panel){if(panel.__diorSharedChatBound)return;panel.__diorSharedChatBound=!0;var role=panel.getAttribute('data-dior-chat-role'),input=panel.querySelector(role==='doctor'?'#dior-doc-chat-input':'#dior-chat-input'),button=panel.querySelector(role==='doctor'?'#dior-doc-chat-send-btn':'#dior-chat-send-btn');function refresh(){request(panel,'get').then(function(r){if(r&&r.success&&r.data){if(r.data.doctor_name)panel.setAttribute('data-doctor-name',r.data.doctor_name);if(r.data.patient_name)panel.setAttribute('data-patient-name',r.data.patient_name);render(panel,r.data.messages||[],role)}}).catch(function(){})}function send(){if(!input)return;var msg=input.value.trim();if(!msg)return;if(button)button.disabled=!0;request(panel,'send',msg).then(function(r){if(r&&r.success){input.value='';refresh()}}).catch(function(){}).finally(function(){if(button)button.disabled=!1;if(input)input.focus()})}if(button)button.addEventListener('click',function(e){e.preventDefault();send()});if(input)input.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();send()}});refresh();window.setInterval(function(){if(document.visibilityState!=='hidden')refresh()},2000)}
function boot(){document.querySelectorAll('[data-dior-chat-role]').forEach(bind)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:!0});else boot()})()